#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// Wiring (see device graph):
// DS1 OLED 0.96" SSD1306 128x64 on SDA=GPIO6, SCL=GPIO7 (XIAO ESP32-C3 D4/D5), addr 0x3C
// SW1 start/stop on D1=GPIO3 (INPUT_PULLUP, LOW=pressed, wake-capable)
// SW2 plus      on D2=GPIO4 (INPUT_PULLUP, wake-capable)
// SW3 minus     on D3=GPIO5 (INPUT_PULLUP, wake-capable)
// Buzzer BZ1 active 3V via NPN Q1: base via 1k from D10=GPIO10; HIGH = beep ON
// LED1 green via 1k from RX=GPIO20; HIGH = on
// BT1 LiPo 500mAh on module BAT pads, charged from USB-C

#define PIN_SW1 3    // D1
#define PIN_SW2 4    // D2
#define PIN_SW3 5    // D3
#define PIN_BUZZ 10  // D10
#define PIN_LED 20   // RX

#define SCREEN_W 128
#define SCREEN_H 64
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

// Timer state
long setSeconds = 5 * 60;      // adjustable preset when idle
long remainMs = 0;
bool running = false;
bool ringing = false;
unsigned long lastTick = 0;
unsigned long lastActivity = 0;
unsigned long ringStart = 0;
const unsigned long IDLE_SLEEP_MS = 60000; // sleep after 60 s idle

struct Btn { int pin; bool last; unsigned long lastChange; bool pressed; };
Btn b1{PIN_SW1, HIGH, 0, false}, b2{PIN_SW2, HIGH, 0, false}, b3{PIN_SW3, HIGH, 0, false};

bool pollBtn(Btn &b) {
  bool r = digitalRead(b.pin);
  unsigned long now = millis();
  bool event = false;
  if (r != b.last && (now - b.lastChange) > 40) { // 40 ms debounce
    b.lastChange = now;
    b.last = r;
    if (r == LOW) event = true; // press edge
  }
  return event;
}

void beep(bool on) {
  digitalWrite(PIN_BUZZ, on ? HIGH : LOW);
  digitalWrite(PIN_LED, on ? HIGH : LOW);
}

void showIdle() {
  display.clearDisplay();
  display.setTextSize(3);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(8, 8);
  int m = setSeconds / 60, s = setSeconds % 60;
  char buf[8]; snprintf(buf, sizeof(buf), "%02d:%02d", m, s);
  display.print(buf);
  display.setTextSize(1);
  display.setCursor(8, 48);
  display.print("+/- set  START stop");
  display.display();
}

void showRunning() {
  long ms = remainMs;
  int m = ms / 60000, s = (ms % 60000) / 1000;
  display.clearDisplay();
  display.setTextSize(3);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(8, 8);
  char buf[8]; snprintf(buf, sizeof(buf), "%02d:%02d", m, s);
  display.print(buf);
  display.setTextSize(1);
  display.setCursor(8, 48);
  display.print(running ? "RUN  STOP" : "PAUSE  START");
  display.display();
}

void showRing() {
  display.clearDisplay();
  display.setTextSize(3);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(4, 8);
  display.print("TIME!");
  display.setTextSize(1);
  display.setCursor(8, 48);
  display.print("press START");
  display.display();
}

void goSleep() {
  beep(false);
  display.ssd1306_command(SSD1306_DISPLAYOFF);
  // Wake on any of the three buttons (active LOW, GPIO3/4/5)
  esp_deep_sleep_enable_gpio_wakeup((1ULL<<PIN_SW1)|(1ULL<<PIN_SW2)|(1ULL<<PIN_SW3), ESP_GPIO_WAKEUP_GPIO_LOW);
  esp_deep_sleep_start();
}

void setup() {
  pinMode(PIN_SW1, INPUT_PULLUP);
  pinMode(PIN_SW2, INPUT_PULLUP);
  pinMode(PIN_SW3, INPUT_PULLUP);
  pinMode(PIN_BUZZ, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  beep(false);
  Wire.begin(); // module default I2C pins SDA/SCL
  bool ok = display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  if (!ok) {
    // Missing display fallback: beep a SOS so the timer still works
    for (int i=0;i<3;i++){ beep(true); delay(150); beep(false); delay(150); }
  }
  remainMs = (long)setSeconds * 1000;
  lastActivity = millis();
  showIdle();
}

void loop() {
  unsigned long now = millis();
  bool e1 = pollBtn(b1), e2 = pollBtn(b2), e3 = pollBtn(b3);
  if (e1 || e2 || e3) lastActivity = now;

  if (ringing) {
    // 2.8 kHz active buzzer: pulse 500 ms on/off + LED flash
    bool phase = ((now - ringStart) / 500) % 2 == 0;
    beep(phase);
    showRing();
    if (e1) { ringing = false; beep(false); running = false; remainMs = (long)setSeconds*1000; showIdle(); }
    if (now - ringStart > 120000) { ringing=false; beep(false); goSleep(); } // stop after 2 min
    return;
  }

  if (!running) {
    if (e2) { setSeconds += 60; if (setSeconds > 99*60+59) setSeconds = 99*60+59; remainMs = (long)setSeconds*1000; showIdle(); }
    if (e3) { setSeconds -= 60; if (setSeconds < 0) setSeconds = 0; remainMs = (long)setSeconds*1000; showIdle(); }
    // long-press style: holding + / - adds seconds via repeat
    if (e1 && setSeconds > 0) { running = true; remainMs = (long)setSeconds*1000; lastTick = now; showRunning(); }
    else if (e1 && setSeconds == 0) { setSeconds = 60; remainMs = 60000; showIdle(); }
    if (!running && (now - lastActivity > IDLE_SLEEP_MS)) goSleep();
  } else {
    // countdown
    unsigned long dt = now - lastTick;
    lastTick = now;
    remainMs -= (long)dt;
    if (remainMs <= 0) { remainMs = 0; running = false; ringing = true; ringStart = now; }
    else showRunning();
    if (e1) { running = false; showRunning(); } // pause
    if (e2) { remainMs += 60000; showRunning(); }
    if (e3) { remainMs -= 60000; if (remainMs < 0) remainMs = 0; showRunning(); }
  }
  delay(50);
}
